import{_ as i,l as r,o as e,c as s,v as t,p as l,x as n,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"进制与位权","description":"","frontmatter":{"title":"进制与位权","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/positional-notation.md","filePath":"cs/positional-notation.md","lastUpdated":1789023840000}'),E={name:"cs/positional-notation.md"};function c(_,a,m,A,u,b){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="进制与位权" tabindex="-1">进制与位权 <a class="header-anchor" href="#进制与位权" aria-label="Permalink to &quot;进制与位权&quot;">​</a></h1><div class="epigraph"><p>同一串符号，只有先约定每一位的权，才变成一个数；权是位置给的，不是符号自己带的。</p><footer>—— 据 Knuth, The Art of Computer Programming, Vol. 2；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/bit-as-distinction">比特作为区分</a>钉死了：先有可分辨的二元状态，再谈编码。本课不重讲判决，也不从「十进制怎么写」另起。缺口是：比特串还没有读法。\\(0110\\) 可以是六，也可以是别的东西；没有位权，加法、溢出和后课的补码都没有对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有了 \\(\\Sigma^n\\)，比较和复制已经够。要把串当成整数，必须指定基 \\(b\\ge 2\\) 和各位的权。否则「进位」没有定义：哪一位满了该往哪送，上一课根本没问。缺口因此不是新的物理区分，而是把串解释成</p> \\[(a_{n-1}\\cdots a_0)_b=\\sum_{i=0}^{n-1}a_i b^i,\\qquad 0\\le a_i\\lt b. \\]<p>二进制只是 \\(b=2\\)、\\(a_i\\in\\{0,1\\}\\)。十六进制是给人读的压缩，每四比特一位，不另造字母表。本课只钉无符号位权；负数、小数点都是后课的缺口。</p><h3 id="位权不是「从左往右念」" tabindex="-1">位权不是「从左往右念」 <a class="header-anchor" href="#位权不是「从左往右念」" aria-label="Permalink to &quot;位权不是「从左往右念」&quot;">​</a></h3><p>日常从高位念起。机器里权是指数：最低位权 \\(b^0\\)，最高位权 \\(b^{n-1}\\)。端序决定字节怎么排进内存，不改变一个字内部的位权。把端序提前塞进本课，会把表示和存储搅在一起。</p><p><span class="marginnote">Knuth 把位权系统写成一般 \\(b\\) 进。Patterson/Hennessy 在整数算术一章默认二进制无符号，再引入补码。本课停在无符号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定宽度 \\(n\\)。可表示的无符号整数是 \\(\\{0,1,\\ldots,2^n-1\\}\\)，一共 \\(2^n\\) 个，与上一课 \\(|\\Sigma^n|\\) 相同，只是现在每个串有一个数值。加法按位加、满 \\(2\\) 进一；超出 \\(2^n-1\\) 的进位被丢掉，就是模 \\(2^n\\)。本课承认模运算会发生，不把「溢出」定义成有符号的两数同号、和异号——那要等<a href="/cs/twos-complement">补码</a>。</p><p>换基是同一整数的不同写法，不是不同的数。从 \\(b\\) 到 \\(c\\)，反复除 \\(c\\) 取余得到新各位。证明用的是带余除法，本课不展开欧几里得算法。</p>',13)),(e(),l(h,null,{default:n(()=>[p(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIT%5B%22%E6%AF%94%E7%89%B9%E4%B8%B2%22%5D%20--%3E%20WEIGHT%5B%22%E7%BA%A6%E5%AE%9A%E5%9F%BA%E4%B8%8E%E4%BD%8D%E6%9D%83%22%5D%0A%20%20WEIGHT%20--%3E%20UINT%5B%22%E6%97%A0%E7%AC%A6%E5%8F%B7%E6%95%B4%E6%95%B0%200%20%E2%80%A6%202%5En-1%22%5D%0A%20%20UINT%20--%3E%20MOD%5B%22%E6%A8%A1%202%5En%20%E5%8A%A0%E6%B3%95%22%5D%0A%20%20MOD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%A1%A5%E7%A0%81%E4%B8%8E%E6%BA%A2%E5%87%BA%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>位权让电路可以对齐同一权的位再加。全加器吃的是三个同权比特，吐出本位和与向更高权的进位；那是后课加法器的对象，这里只要求权已经排好。固定 \\(n\\) 之后，数值集合有限，相等仍是串相等，因为无符号编码是双射。</p><p>\\(n\\) 是资源：字长决定无符号上限。总线一次搬 \\(n\\) 比特，搬的是这个编码，不是「抽象的整数」。后课的指令立即数、地址、偏移，默认都先按无符号或补码读，而不是按十进制读。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入符号位，不把最高位解释成负权。原码、反码、补码是下一课才分的三条路。也不引入小数点：定点只是把某位的权改成 \\(b^{-k}\\)，本课连负指数都还没有。Shannon 熵、字符编码都不在这里；串的数值读法与串作为消息的读法不是一回事。</p><p>后课默认：谈到无符号整数、地址、掩码，它们是固定宽度的位权编码，加法默认模 \\(2^n\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>比特串加上基与位权才成为无符号整数。</li><li>宽度 \\(n\\) 给出 \\(\\{0,\\ldots,2^n-1\\}\\)；加法超出则模 \\(2^n\\)。</li><li>换基不换数；十六进制只是二进制的缩写。</li><li>符号、溢出语义、定点与浮点都是后课缺口。</li><li>出处：Knuth, TAOCP Vol. 2；Patterson and Hennessy, <em>Computer Organization and Design</em> (RISC-V) 整数表示。</li></ul>',8))])}const T=i(E,[["render",c]]);export{f as __pageData,T as default};
